package dev.oqthara.runtime;

import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Collection helpers used by generated bytecode. Like {@link Arithmetic}, every method
 * delegates to {@link Values} so compiled code and the interpreter cannot drift.
 */
public final class Collections {
    private Collections() {
    }

    public static Object newList() {
        return new ArrayList<>();
    }

    @SuppressWarnings("unchecked")
    public static void addToList(Object list, Object item) {
        ((List<Object>) list).add(item);
    }

    public static Object newSet() {
        return new OqSet();
    }

    /**
     * Builds a tuple. Generated code fills an ordinary list and hands it over, so the
     * tuple itself is the only immutable object in the path.
     */
    public static Object newTuple(Object items) {
        @SuppressWarnings("unchecked")
        List<Object> values = (List<Object>) items;
        return new OqTuple(values);
    }

    @SuppressWarnings("unchecked")
    public static void addToSet(Object set, Object item) {
        ((Set<Object>) set).add(item);
    }

    public static Object newMap() {
        return new OqMap();
    }

    @SuppressWarnings("unchecked")
    public static void putInMap(Object map, Object key, Object value) {
        ((Map<Object, Object>) map).put(key, value);
    }

    public static Object index(Object target, Object key) {
        return Values.index(target, key, Errors.current());
    }

    public static Object slice(Object target, Object from, Object to, Object step) {
        return Values.slice(target, from, to, step, Errors.current());
    }

    public static void setIndex(Object target, Object key, Object value) {
        Values.setIndex(target, key, value, Errors.current());
    }

    public static Object length(Object value) {
        return Values.length(value, Errors.current());
    }

    /**
     * The destructuring parts of a value, checked against the target count in one place so
     * compiled code and the interpreter reject the same programs with the same words.
     */
    public static Object destructure(Object value, int count) {
        return Values.destructuringParts(value, count, Errors.current());
    }

    /**
     * Membership, in the lowering's stack order: the item is pushed first, then the
     * container. The interpreter calls {@code Values.contains(container, item)}.
     */
    public static Object contains(Object item, Object container) {
        return Values.contains(container, item, Errors.current());
    }

    public static Object rangeInclusive(Object from, Object to) {
        Span span = Errors.current();
        return new OqRange(Values.wholeNumber(from, span), Values.wholeNumber(to, span), true);
    }

    public static Object rangeExclusive(Object from, Object to) {
        Span span = Errors.current();
        return new OqRange(Values.wholeNumber(from, span), Values.wholeNumber(to, span), false);
    }

    /**
     * The range a {@code for x in a to b} / {@code a until b} counter loop walks.
     *
     * <p>The direction comes from the bounds: counting up when {@code from <= to}, down
     * otherwise. That is the counter-loop rule, and it is deliberately not the range-literal
     * rule, where {@code 5 to 1} is an empty range because a literal advances by one. Sharing
     * this method is what stops the interpreter and compiled code from disagreeing about
     * fractional bounds, and what stops the loop from ending at {@code Long.MAX_VALUE} by
     * wrapping to {@code Long.MIN_VALUE} (the old looping form added the step and re-tested the
     * bound, which never finished).
     */
    public static Object counterRange(Object from, Object to, boolean inclusive) {
        Span span = Errors.current();
        long start = Values.wholeNumber(from, span);
        long bound = Values.wholeNumber(to, span);
        return new OqRange(start, bound, inclusive, start <= bound ? 1 : -1);
    }

    public static Object iterator(Object value) {
        return Values.iterable(value, Errors.current()).iterator();
    }

    public static Object hasNext(Object iterator) {
        return ((Iterator<?>) iterator).hasNext();
    }

    public static Object next(Object iterator) {
        return ((Iterator<?>) iterator).next();
    }
}
